let SRV = false;
async function srv(action, body = {}) {
  const r = await fetch("/api/game/" + action, { method: "POST", credentials: "same-origin", headers: { "content-type": "application/json" }, body: JSON.stringify(body) });
  const out = await r.json().catch(() => ({}));
  if (out.state) { const pack = save.pack; save = normalizeSave(out.state); save.pack = pack; }
  if (!r.ok) throw new Error(out.error || "Le serveur ne répond pas. Réessaie dans un instant.");
  if (out.titles?.length) announceTitles(out.titles);
  return out;
}
let DB = null, USER = null, ME = null, canShare = false;
const shared = { feed: [], players: [], market: [], trades: [] };
// ===== Prédictions (comme sur le Discord de Billy) =====
// Billy (éditeur) crée les questions et valide les bonnes réponses ; chaque joueur vote une fois par question.
const pred = { questions: [], mine: {}, all: [], scores: {} };
function subscribePred() {
  const map = (s) => s.docs.map((d) => ({ id: d.id, ...d.data() }));
  DB.collection("predq").orderBy("t", "asc").onSnapshot((s) => { pred.questions = map(s); creditPredictions(); predChanged(); }, () => {});
  DB.doc("pred/scores").onSnapshot((s) => { pred.scores = (s.exists && s.data().scores) || {}; predChanged(); }, () => {});
  DB.doc("votes/" + ME).onSnapshot((s) => { pred.mine = (s.exists && s.data().answers) || {}; creditPredictions(); predChanged(); }, () => {});
  if (IS_ADMIN) DB.collection("votes").onSnapshot((s) => { pred.all = map(s); predChanged(); }, () => {});
}
let predT;
function predChanged() { clearTimeout(predT); predT = setTimeout(() => { if (!opening && $("overlay").hidden && view === "pred" && !document.activeElement?.closest?.("#pqForm")) draw(); }, 150); }
let predClaimT;
function creditPredictions() {
  if (SRV) {
    clearTimeout(predClaimT);
    predClaimT = setTimeout(async () => {
      const r = await srv("predictions").catch(() => null);
      if (r?.won) toast(`Bonne prédiction${r.won > 1 ? "s" : ""} ! +${r.value} ◆`);
      header();
    }, 400);
    return;
  }
  const won = pred.questions.filter((q) => q.status === "resolved" && pred.mine[q.id] === q.answer && !save.predPaid.includes(q.id));
  if (!won.length) return;
  for (const q of won) save.predPaid.push(q.id);
  const value = won.reduce((t, q) => t + predRewardOf(q), 0);
  save.chakra += value; trackS(save, "predwin", won.length); persist(); header();
  toast(`Bonne prédiction${won.length > 1 ? "s" : ""} ! +${value} ◆`);
}
async function vote(qid, idx) {
  const q = pred.questions.find((x) => x.id === qid);
  if (!q || !predOpen(q)) return toast("Les votes sont fermés pour cette question.");
  const first = pred.mine[qid] == null, prev = pred.mine;
  pred.mine = { ...pred.mine, [qid]: idx }; draw();
  try {
    if (SRV) { await srv("vote", { qid, idx }); creditPredictions(); }
    else { await DB.doc("votes/" + ME).set({ uid: ME, answers: pred.mine, t: Date.now() }); if (first) { track("predict"); persist(); } }
    if (first) toast("Vote enregistré. Tu peux le changer tant que les votes sont ouverts.");
  } catch (e) { pred.mine = prev; draw(); toast(SRV ? e.message : "Ton vote n'est pas passé. Il faut l'accès « Contributeur »."); }
}
async function recomputeScores() {
  // relit les questions (le serveur y a noté l'heure de fermeture) et ne compte que les votes faits à temps
  const [s, qs] = await Promise.all([DB.collection("votes").get(), DB.collection("predq").get()]);
  const questions = qs.docs.map((d) => ({ id: d.id, ...d.data() }));
  const scores = {};
  for (const d of s.docs) {
    const v = d.data(), uid = v.uid || d.id;
    scores[uid] = 0;
    for (const q of questions) if (q.status === "resolved" && v.answers?.[q.id] === q.answer && predVoteOk(q, v)) scores[uid] += q.points || 1;
  }
  await DB.doc("pred/scores").set({ scores, t: Date.now() });
}
async function adminPred(action, qid, value) {
  const ref = DB.doc("predq/" + qid);
  try {
    if (action === "close") await ref.update({ status: "closed" });
    if (action === "open") await ref.update({ status: "open", answer: null, endsAt: null });
    if (action === "deadline") { const t = value ? new Date(value).getTime() : null; await ref.update({ endsAt: t }); pred.questions = pred.questions.map((q) => (q.id === qid ? { ...q, endsAt: t } : q)); toast(t ? "Fin des votes enregistrée." : "Plus de limite de temps."); draw(); }
    if (action === "resolve") { await ref.update({ status: "resolved", answer: value }); pred.questions = pred.questions.map((q) => (q.id === qid ? { ...q, status: "resolved", answer: value } : q)); await recomputeScores(); toast("Bonne réponse validée, points mis à jour."); }
    if (action === "reward") { await ref.update({ reward: predRewardOf({ reward: value }) }); toast("Récompense mise à jour."); }
    if (action === "delete") { await ref.delete(); pred.questions = pred.questions.filter((q) => q.id !== qid); await recomputeScores(); toast("Question supprimée."); }
  } catch (e) { toast("Action refusée : il faut être éditeur de l'app."); }
}
async function addQuestion(form) {
  const text = $("pqText").value.trim(), options = $("pqOptions").value.split("\n").map((s) => s.trim()).filter(Boolean);
  const dur = +($("pqDur")?.value || 0), endsAt = dur ? Date.now() + dur * 3600000 : null;
  const ep = +$("pqEp").value || 2, points = Math.max(1, Math.min(10, +$("pqPoints").value || 1)), reward = predRewardOf({ reward: $("pqReward").value });
  if (!text || options.length < 2) return toast("Écris une question et au moins 2 réponses (une par ligne).");
  try {
    await DB.collection("predq").add({ ep, text, options: options.slice(0, 6), points, reward, status: "open", answer: null, endsAt, t: Date.now() });
    form.reset(); document.activeElement?.blur(); toast("Question publiée."); draw();
  } catch (e) { toast("Publication refusée : il faut être éditeur de l'app."); }
}


