function applyConfig(data) { CONFIG = configFrom(data); }
function saveConfig() {
  if (!DB || !IS_ADMIN) return;
  clearTimeout(configT);
  configT = setTimeout(() => DB.doc("config/game").set(JSON.parse(JSON.stringify(CONFIG))).then(() => toast("Réglages enregistrés.")).catch(() => toast("Enregistrement refusé : il faut être éditeur de l'app.")), 500);
}
const epLabel = (n) => (n >= HIDDEN ? "Caché" : `Épisode ${n}`);
const epOptions = (sel, hidden) => [...Array(EP_MAX)].map((_, i) => `<option value="${i + 1}" ${sel === i + 1 ? "selected" : ""}>Épisode ${i + 1}</option>`).join("") + (hidden ? `<option value="${HIDDEN}" ${sel >= HIDDEN ? "selected" : ""}>Caché</option>` : "");

document.addEventListener("change", (e) => {
  const t = e.target;
  if (!IS_ADMIN) return;
  if (t.dataset.cfg === "def") CONFIG.def = +t.value;
  else if (t.dataset.prog) { if (t.value === "") delete CONFIG.progress[t.dataset.prog]; else CONFIG.progress[t.dataset.prog] = +t.value; }
  else if (t.dataset.ep) CONFIG.ep[t.dataset.ep] = +t.value;
  else if (t.dataset.feat) { if (t.checked) delete CONFIG.features[t.dataset.feat]; else CONFIG.features[t.dataset.feat] = false; }
  else if (t.dataset.extra) {
    const uid = t.dataset.uidFor, list = new Set(CONFIG.extra[uid] || []);
    if (t.checked) list.add(t.dataset.extra); else list.delete(t.dataset.extra);
    CONFIG.extra[uid] = [...list];
  } else return;
  saveConfig();
});

function persist() {
  if (SRV) return;  // le serveur garde déjà tout
  announceTitles(grantTitlesS(save));
  save.updated = Date.now();
  try { localStorage.setItem(LS, JSON.stringify(save)); } catch (e) {}
  if (remote) { clearTimeout(pushT); pushT = setTimeout(() => remote.set(save).catch(() => { remote = null; }), 600); }
  publishPlayer();
}
async function connect() {
  try {
    if (!window.claude?.use) return;
    const [db, user] = await Promise.all([window.claude.use("db"), window.claude.use("user")]);
    const id = await user?.id();
    if (!db || !id) return;
    DB = db; USER = user; ME = id;
    IS_ADMIN = !!(await user.canEdit?.());
    IS_DEV = !!(window.DISCORD_LOGIN && (await window.discordMe())?.dev);
    canShare = (await user.can?.("data.write")) !== false;
    if (window.DISCORD_LOGIN) {
      const guest = save.opened ? save : null;
      SRV = true;
      canShare = true; // connecté avec Discord : tout est ouvert (le serveur vérifie lui-même), membre du QG ou pas
      const r = await srv("state", { guest });
      if (r.imported === "invité") toast("Tes cartes communes jouées en invité ont été reprises sur ton compte Discord.");
      await creaLoad(true); // persos, cartes et cosmétiques créés depuis l'app
      subscribeShared();
      subscribePred();
      MYNAME = (await window.discordMe())?.name || "";
      pulse();
      MYNAME = (await window.discordMe())?.name || MYNAME;
      subscribeExtra(); loadAccount();
      if (!opening) draw();
      return;
    }
    const ref = db.doc("data/users/" + id + "/rzlol");
    const snap = await ref.get();
    remote = ref;
    const r = snap.exists ? snap.data() : null;
    if (r && (r.updated || 0) >= (save.updated || 0)) {
      save = normalizeSave(r);
      try { localStorage.setItem(LS, JSON.stringify(save)); } catch (e) {}
    } else persist();
    subscribeShared();
    subscribePred();
    MYNAME = (await user.me?.())?.name || "";
    if (chat.open) subscribeChat();
    subscribeExtra(); loadAccount();
    publishPlayer();
    if (!opening) draw();
  } catch (e) { remote = null; }
}

// ===== Données partagées : tirages en direct, classement, marché =====
function subscribeShared() {
  const map = (s) => s.docs.map((d) => ({ id: d.id, ...d.data() }));
  DB.doc("config/game").onSnapshot((s) => { applyConfig(s.exists ? s.data() : null); if (view !== "admin") sharedChanged(); }, () => {});
  DB.collection("feed").orderBy("t", "desc").limit(30).onSnapshot((s) => { shared.feed = map(s); sharedChanged(); }, () => {});
  DB.collection("players").orderBy("cards", "desc").limit(50).onSnapshot((s) => { shared.players = map(s); sharedChanged(); }, () => {});
  DB.collection("market").orderBy("t", "desc").limit(300).onSnapshot((s) => { shared.market = map(s); collectSales(); wishAlerts(); sharedChanged(); }, () => {});
  if (SRV) DB.collection("trades").orderBy("t", "desc").limit(100).onSnapshot((s) => {
    const before = pendingTrades().length; shared.trades = map(s);
    if (pendingTrades().length > before) toast("Nouvelle proposition d'échange : va voir dans Marché → Échanges.");
    sharedChanged();
  }, () => {});
}
