// ===== Marché =====
async function confirmSell(form) {
  const id = form.dataset.id, gold = !!form.dataset.gold, price = Math.round(+$("sellPrice").value);
  if (!(price >= 5 && price <= 9999)) return toast("Choisis un prix entre 5 et 9999 ◆.");
  if (SRV) {
    try { await srv("market/sell", { id, gold, price, withDesign: !!$("sellDz")?.checked }); $("overlay").hidden = true; toast("Carte mise en vente."); marketTab = "mine"; nav("market"); }
    catch (e) { toast(e.message); }
    return;
  }
  const o = { ...own(id) };
  if (gold ? o.gold < 1 : o.n < 1) return toast("Tu n'as plus cette carte.");
  if (gold) o.gold--; else o.n--;
  save.owned[id] = o; persist();
  try {
    await DB.collection("market").add({ seller: ME, card: id, gold, price, status: "open", t: Date.now() });
    track("sell"); persist();
    $("overlay").hidden = true; toast("Carte mise en vente."); marketTab = "mine"; nav("market");
  } catch (e) {
    if (gold) o.gold++; else o.n++;
    save.owned[id] = o; persist();
    toast("La mise en vente n'a pas marché. Réessaie dans un instant.");
  }
}
async function buy(lid) {
  if (SRV) {
    try { const r = await srv("market/buy", { lid }); toast(`${PEOPLE[byId[r.card].who].name} rejoint ta collection : −${r.price} ◆`); }
    catch (e) { toast(e.message); }
    return draw();
  }
  const l = shared.market.find((x) => x.id === lid);
  if (!l || l.status !== "open") return toast("Cette carte vient d'être vendue.");
  if (save.chakra < l.price) return toast(`Il te faut ${l.price} ◆.`);
  const ref = DB.doc("market/" + lid);
  try {
    const lease = await ref.acquire({ holder: ME, ttlMs: 8000 });
    if (!lease.acquired) return toast("Quelqu'un est en train de l'acheter.");
    const s = await ref.get();
    if (!s.exists || s.data().status !== "open") return toast("Cette carte vient d'être vendue.");
    await ref.update({ status: "sold", buyer: ME, soldAt: Date.now() });
    save.chakra -= l.price;
    const o = { ...own(l.card) }; if (l.gold) o.gold++; else o.n++; if (!o.first) o.first = Date.now();
    save.owned[l.card] = o; persist(); draw();
    toast(`${PEOPLE[byId[l.card].who].name} rejoint ta collection : −${l.price} ◆`);
  } catch (e) { toast("L'achat n'a pas marché. Réessaie dans un instant."); }
}
async function cancelSale(lid) {
  if (SRV) {
    try { await srv("market/cancel", { lid }); toast("Vente retirée, la carte revient dans ta collection."); }
    catch (e) { toast(e.message); }
    return draw();
  }
  const l = shared.market.find((x) => x.id === lid);
  if (!l || l.seller !== ME || l.status !== "open") return;
  try {
    await DB.doc("market/" + lid).update({ status: "cancelled" });
    const o = { ...own(l.card) }; if (l.gold) o.gold++; else o.n++;
    save.owned[l.card] = o; persist(); draw();
    toast("Vente retirée, la carte revient dans ta collection.");
  } catch (e) { toast("Impossible de retirer la vente pour l'instant."); }
}

