// ===== Chat du QG et notifications =====
// Sur le site Cloudflare, tout passe par /api/game/pulse (un seul appel régulier) ;
// sur claude.ai, le chat utilise la base partagée de l'app et les notifs restent locales.
const esc = (t) => String(t ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
const lsGet = (k) => { try { return localStorage.getItem(k); } catch (e) { return null; } };
const lsSet = (k, v) => { try { localStorage.setItem(k, v); } catch (e) {} };
const chat = { msgs: [], open: false, last: null, seen: +(lsGet("rzlol-chat-seen") || 0), card: null, loaded: false, sub: false };
const notif = { items: [], read: 0, unread: 0, open: false, max: 0, loaded: false };
let MYNAME = "";
const NICON = { sold: "◆", trade: "⇄", mention: "@", episode: "★", pred: "?", announce: "!" };
const canChat = () => (SRV ? true : !!(DB && ME && canShare));

// notifs touchées : on les retire de la cloche (sur cet appareil)
function notifOff() { try { const o = JSON.parse(lsGet("rzlol-notif-off") || "{}"); return { todo: o.todo || {}, ids: o.ids || [] }; } catch (e) { return { todo: {}, ids: [] }; } }
function dismissNotif(el) {
  const o = notifOff();
  if (el.dataset.ntodo) o.todo[el.dataset.ntodo] = Date.now();
  if (el.dataset.nid) o.ids = [...o.ids, +el.dataset.nid].slice(-300);
  lsSet("rzlol-notif-off", JSON.stringify(o)); badges();
}
// supprimer une notification (la croix) ou toutes : retirées de la cloche sur cet appareil
document.addEventListener("click", (e) => {
  const d = e.target.closest("[data-ndel]"), c = e.target.closest("[data-nclear]");
  if (!d && !c) return;
  e.stopPropagation(); e.preventDefault();
  const o = notifOff(), ids = d ? [+d.dataset.ndel] : shownNotifs().map((n) => n.id);
  o.ids = [...o.ids, ...ids].slice(-300); lsSet("rzlol-notif-off", JSON.stringify(o));
  markRead(); badges(); drawNotifs();
}, true);
const shownNotifs = () => { const ids = new Set(notifOff().ids); return notif.items.filter((n) => !ids.has(n.id)); };
function bellCount() { return notif.unread + todos().length; }
const chatUnread = () => chat.msgs.filter((m) => m.ts > chat.seen && m.uid !== ME).length;
function badges() {
  const b = $("bellN"), c = $("chatN"); if (!b) return;
  const n = bellCount(), u = (chat.open ? 0 : chatUnread()) + (chat.req || 0) + (chat.dmUn || 0);
  b.hidden = !n; b.textContent = n > 9 ? "9+" : n;
  c.hidden = !u; c.textContent = u > 9 ? "9+" : u;
  document.title = (n + u ? `(${n + u}) ` : "") + "Re : LOL";
}

// --- notifications de l'appareil (quand l'onglet est en arrière-plan) ---
const pushOn = () => lsGet("rzlol-push") === "1" && "Notification" in window && Notification.permission === "granted";
function pushOS(text) {
  if (!pushOn() || !document.hidden) return;
  try { new Notification("Re : LOL", { body: text, tag: "rzlol-" + text.slice(0, 40) }); } catch (e) {}
}
async function togglePush() {
  if (!("Notification" in window)) return toast("Ton navigateur ne gère pas les notifications.");
  if (pushOn()) { lsSet("rzlol-push", "0"); toast("Notifications de l'appareil coupées."); return drawNotifs(); }
  const p = await Notification.requestPermission();
  if (p !== "granted") return toast("Autorise les notifications dans ton navigateur pour les recevoir.");
  lsSet("rzlol-push", "1"); toast("C'est bon : tu seras prévenu même quand l'onglet est en arrière-plan."); drawNotifs();
}

// --- cloche ---
function toggleNotifs(force) {
  notif.open = force ?? !notif.open;
  $("notifPanel").hidden = !notif.open; $("bellBtn").setAttribute("aria-expanded", notif.open);
  if (notif.open) { drawNotifs(); markRead(); }
}
function markRead() {
  if (!SRV || !notif.max || notif.read >= notif.max) return;
  notif.read = notif.max; notif.unread = 0; badges();
  srv("notifs/read", { last: notif.max }).catch(() => {});
}
function goTo(go) {
  toggleNotifs(false);
  if (go === "chat") return openChat(true);
  if (go === "friends") return openFriends();
  if (!go) return;
  if (go === "trades" || go === "market") { marketTab = go === "trades" ? "trades" : "mine"; nav("market"); } else nav(go);
}

// --- appel régulier au serveur ---
let pulseT = null, pulsing = false;
function schedulePulse() { clearTimeout(pulseT); if (SRV) pulseT = setTimeout(pulse, chat.open && !document.hidden ? 3000 : window.__asleep?.() || document.hidden ? 5 * 60e3 : 10000); }
addEventListener("rz-wake", () => { if (SRV && !pulsing) { clearTimeout(pulseT); pulse(); } });
async function pulse() {
  if (!SRV || pulsing) return;
  pulsing = true;
  try {
    const r = await srv("pulse", { after: chat.last });
    if (r.gone?.length) chat.msgs = chat.msgs.filter((m) => !r.gone.includes(m.id));
    if (r.chat?.length) {
      chat.msgs = chat.loaded ? [...chat.msgs, ...r.chat].slice(-200) : r.chat;
      chat.last = chat.msgs[chat.msgs.length - 1].id;
      if (chat.loaded) for (const m of r.chat) if (m.uid !== ME && m.kind === "msg" && MYNAME && m.text.toLowerCase().includes("@" + MYNAME.toLowerCase())) pushOS(`${m.name} : ${m.text}`);
    } else if (!chat.loaded) chat.last = 0;
    if (!chat.loaded && !chat.seen) chat.seen = chat.msgs.length ? chat.msgs[chat.msgs.length - 1].ts : Date.now();
    chat.loaded = true;
    const n = r.notifs;
    if (n) {
      const fresh = n.items.filter((x) => x.id > notif.max && x.id > n.read);
      notif.items = n.items; notif.read = Math.max(notif.read, n.read);
      notif.unread = n.items.filter((x) => x.id > notif.read).length;
      notif.max = n.items.reduce((m, x) => Math.max(m, x.id), 0);
      if (notif.loaded && fresh.length) {
        toast(fresh[0].text); fresh.forEach((x) => pushOS(x.text));
        // une vente ou un échange a changé ta collection : on la recharge
        if (fresh.some((x) => x.kind === "sold" || x.kind === "trade")) srv("state").then(() => { if (!opening && $("overlay").hidden) draw(); }).catch(() => {});
      }
      notif.loaded = true;
      if (notif.open) { drawNotifs(); markRead(); }
    }
    if (r.social) { const ch = r.social.req !== chat.req; chat.req = r.social.req; chat.dmUn = r.social.dm; if (chat.open && chat.tab === "amis" && !FR.peer && ch) openFriends(); }
    if (chat.open && chat.tab === "amis" && FR.peer) await pollDM();
    else if (chat.open) drawChatList();
    badges();
  } catch (e) {}
  pulsing = false;
  schedulePulse();
}
document.addEventListener("visibilitychange", () => { if (!document.hidden && SRV) pulse(); });

// --- chat ---
function subscribeChat() {
  if (SRV || !DB || chat.sub) return;
  chat.sub = true;
  DB.collection("chat").orderBy("t", "desc").limit(80).onSnapshot((s) => {
    chat.msgs = s.docs.map((d) => { const m = d.data(); return { id: d.id, uid: m.uid, kind: m.kind || "msg", text: String(m.text || "").slice(0, 300), card: m.card || null, gold: !!m.gold, ts: m.t || 0 }; }).reverse();
    if (!chat.loaded && !chat.seen) chat.seen = Date.now();
    chat.loaded = true;
    if (chat.open) drawChatList();
    badges();
  }, () => {});
}
function openChat(open) {
  chat.open = open; $("chatPanel").hidden = !open; $("chatFab").hidden = open;
  if (open) { toggleNotifs(false); drawChat(); subscribeChat(); if (SRV) pulse(); setTimeout(() => $("chatIn")?.focus(), 50); }
  else schedulePulse();
  badges();
}
async function sendChat() {
  const inp = $("chatIn"), text = inp.value.trim(), card = chat.card;
  if (!text && !card) return;
  const body = { text, card: card?.id || null, gold: !!card?.gold };
  inp.value = ""; chat.card = null; $("chatAtt").hidden = true; $("chatAtt").innerHTML = "";
  try {
    if (SRV) { await srv("chat/send", body); if (chat.draft) { chat.draft = ""; drawChat(); } await pulse(); }
    else { await DB.collection("chat").add({ uid: ME, kind: "msg", text: text.slice(0, 300), card: body.card, gold: body.gold, t: Date.now() }); track("chat"); persist(); }
  } catch (e) { inp.value = text; chat.card = card; toast(e.message || "Message pas envoyé."); }
}
async function deleteChat(id) {
  try { await srv("chat/delete", { id: +id }); chat.msgs = chat.msgs.filter((m) => m.id !== +id); drawChatList(); } catch (e) { toast(e.message); }
}
async function announce(form) {
  const text = form.querySelector("textarea").value.trim();
  if (!text) return toast("Écris l'annonce.");
  try { await srv("announce", { text }); form.reset(); toast("Annonce envoyée à tout le QG."); pulse(); } catch (e) { toast(e.message); }
}
document.addEventListener("click", (e) => {
  const t = e.target;
  if (t.closest("#bellBtn")) return toggleNotifs();
  if (notif.open && !t.closest("#notifPanel")) toggleNotifs(false);
  if (t.closest("#chatFab")) return openChat(true);
  const ng = t.closest("[data-ngo]"); if (ng) { dismissNotif(ng); if (!ng.dataset.ngo) return drawNotifs(); return goTo(ng.dataset.ngo); }
  const del = t.closest("[data-chatdel]"); if (del) return deleteChat(del.dataset.chatdel);
  const mn = t.closest("[data-mention]"); if (mn && $("chatIn")) { const i = $("chatIn"); i.value = (i.value ? i.value.replace(/\s*$/, " ") : "") + "@" + mn.dataset.mention + " "; return i.focus(); }
  const act = t.closest("[data-act]")?.dataset.act;
  if (act === "notif-read") { markRead(); return drawNotifs(); }
  if (act === "notif-push") return togglePush();
  if (act === "chat-close") return openChat(false);
  if (act === "chat-card") return pickChatCard();
  if (act === "chat-uncard") { chat.card = null; $("chatAtt").hidden = true; $("chatAtt").innerHTML = ""; }
});
document.addEventListener("submit", (e) => {
  if (e.target.id === "chatForm") { e.preventDefault(); sendChat(); }
  if (e.target.id === "annForm") { e.preventDefault(); announce(e.target); }
  if (e.target.id === "chatCardForm") {
    e.preventDefault();
    const [id, g] = $("chatCardSel").value.split("|");
    chat.card = { id, gold: !!g }; $("overlay").hidden = true;
    const att = $("chatAtt"); if (att) { att.innerHTML = `${cardChip(id, !!g)}<button class="linkbtn" type="button" data-act="chat-uncard">Retirer</button>`; att.hidden = false; }
    $("chatIn")?.focus();
  }
});
document.addEventListener("keydown", (e) => { if (e.key === "Escape") { if (chat.open && $("overlay").hidden) openChat(false); toggleNotifs(false); } });
